#include "expense.h"
#include "date_utils.h"
#include "storage.h"
#include "ui.h"
#include "validation.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

const char *const CATEGORY_NAMES[CATEGORY_COUNT] = {"Food","Transport","Education","Shopping","Entertainment","Hostel/Rent","Mobile/Internet","Healthcare","Other"};
const char *const PAYMENT_NAMES[PAYMENT_COUNT] = {"Cash","UPI","Card"};
const char *categoryName(const Transaction *t){return t->expense.category==OTHER&&t->expense.categoryLabel[0]?t->expense.categoryLabel:CATEGORY_NAMES[t->expense.category];}
int categoryFromName(const char *name){for(int i=0;i<CATEGORY_COUNT;i++)if(strcmp(name,CATEGORY_NAMES[i])==0)return i;return -1;}
size_t categoryIndexForTransaction(const AppState *a,const Transaction *t){if(t->expense.category!=OTHER||!t->expense.categoryLabel[0])return (size_t)t->expense.category;for(size_t i=0;i<a->categoryCount;i++)if(strcmp(a->customCategories[i],t->expense.categoryLabel)==0)return CATEGORY_COUNT+i;return OTHER;}
const char *categoryDisplayNameAt(const AppState *a,size_t i){if(i<CATEGORY_COUNT)return CATEGORY_NAMES[i];if(i<CATEGORY_COUNT+a->categoryCount)return a->customCategories[i-CATEGORY_COUNT];return "Unknown";}
int findExpenseById(const AppState *a,int id){for(size_t i=0;i<a->transactionCount;i++)if(a->transactions[i].expense.id==id)return (int)i;return -1;}
bool reserveTransactions(AppState *a,size_t n){if(n>MAX_RECORDS)return false;if(n<=a->transactionCapacity)return true;size_t cap=a->transactionCapacity?a->transactionCapacity:16;while(cap<n){if(cap>MAX_RECORDS/2){cap=MAX_RECORDS;break;}cap*=2;}Transaction *p=realloc(a->transactions,cap*sizeof *p);if(!p)return false;a->transactions=p;a->transactionCapacity=cap;return true;}
bool reserveBudgets(AppState *a,size_t n){if(n>MAX_BUDGETS)return false;if(n<=a->budgetCapacity)return true;size_t cap=a->budgetCapacity?a->budgetCapacity:8;while(cap<n)cap*=2;if(cap>MAX_BUDGETS)cap=MAX_BUDGETS;Budget *p=realloc(a->budgets,cap*sizeof *p);if(!p)return false;a->budgets=p;a->budgetCapacity=cap;return true;}
bool reserveCategories(AppState *a,size_t n){if(n>MAX_CATEGORIES)return false;if(n<=a->categoryCapacity)return true;size_t cap=a->categoryCapacity?a->categoryCapacity:8;while(cap<n)cap*=2;if(cap>MAX_CATEGORIES)cap=MAX_CATEGORIES;void *p=realloc(a->customCategories,cap*sizeof *a->customCategories);if(!p)return false;a->customCategories=p;a->categoryCapacity=cap;return true;}
void appStateFree(AppState *a){free(a->transactions);free(a->budgets);free(a->customCategories);memset(a,0,sizeof *a);}

static bool confirm(const char *prompt){char s[16];if(!readLine(prompt,s,sizeof s))return false;char *p=s;while(isspace((unsigned char)*p))p++;return tolower((unsigned char)*p)=='y';}
static int unusedId(AppState *a){int id=a->nextId>0?a->nextId:1;for(size_t tries=0;tries<=a->transactionCount;tries++){if(findExpenseById(a,id)<0)return id;id=id==2147483647?1:id+1;}return 0;}
static int chooseCategory(const AppState *a,ExpenseCategory *category,char *label){printInfo("Available categories");for(int i=0;i<CATEGORY_COUNT;i++)printf("  %2d  %s\n",i+1,CATEGORY_NAMES[i]);for(size_t i=0;i<a->categoryCount;i++)printf("  %2zu  %s (custom)\n",(size_t)CATEGORY_COUNT+i+1,a->customCategories[i]);int n=(int)CATEGORY_COUNT+(int)a->categoryCount,k;if(!readInt("Select category: ",1,n,&k))return 0;if(k<=(int)CATEGORY_COUNT){*category=(ExpenseCategory)(k-1);label[0]=0;}else{*category=OTHER;snprintf(label,CATEGORY_NAME_SIZE,"%s",a->customCategories[k-(int)CATEGORY_COUNT-1]);}return 1;}
static int choosePayment(Transaction *t){int p;if(!readInt("Payment (1 Cash, 2 UPI, 3 Card): ",1,3,&p))return 0;t->paymentType=(PaymentType)(p-1);memset(&t->paymentDetails,0,sizeof t->paymentDetails);
    if(t->paymentType==UPI){if(!readOptionalString("UPI ID (optional, no PIN): ",t->paymentDetails.upiId,sizeof t->paymentDetails.upiId))return 0;}
    else if(t->paymentType==CARD){char digits[16];for(;;){if(!readRequiredString("Card last four digits only: ",digits,sizeof digits))return 0;if(strlen(digits)==4&&digits[0]>='0'&&digits[0]<='9'&&digits[1]>='0'&&digits[1]<='9'&&digits[2]>='0'&&digits[2]<='9'&&digits[3]>='0'&&digits[3]<='9')break;printError("Enter exactly four digits.");}memcpy(t->paymentDetails.cardLastFourDigits,digits,5);}
    else if(!readOptionalString("Cash note (optional): ",t->paymentDetails.cashNote,sizeof t->paymentDetails.cashNote))return 0;
    return 1;}
static int validDateInput(const char *s){Date d;return parseDate(s,&d);}
int addExpense(AppState *a){if(a->transactionCount>=MAX_RECORDS){printError("Transaction limit reached.");return 0;}Transaction t;memset(&t,0,sizeof t);t.expense.id=unusedId(a);if(!t.expense.id){printError("Could not allocate a unique ID.");return 0;}
    for(;;){if(!readRequiredString("Date (DD-MM-YYYY): ",t.expense.date,sizeof t.expense.date))return 0;if(validDateInput(t.expense.date))break;printError("Invalid calendar date.");}
    if(!chooseCategory(a,&t.expense.category,t.expense.categoryLabel)||!readRequiredString("Description: ",t.expense.description,sizeof t.expense.description))return 0;
    if(!readDouble("Amount in Rs. (positive): ",0.0000001,1000000000,&t.expense.amount)||!validateAmount(t.expense.amount)||!choosePayment(&t))return 0;
    printTransaction(&t);if(!confirm("Save this expense? (y/N): ")){printInfo("Expense cancelled.");return 0;}
    if(!reserveTransactions(a,a->transactionCount+1)){printError("Memory allocation failed.");return 0;}a->transactions[a->transactionCount]=t;a->transactionCount++;
    if(!saveExpenses(a)){a->transactionCount--;printError("Expense was not saved; in-memory change rolled back.");return 0;}a->nextId=t.expense.id==2147483647?1:t.expense.id+1;printSuccess("Expense saved successfully.");return 1;}

void viewExpenses(const AppState *a){if(!a->transactionCount){printInfo("No expense records found.");return;}printSection("ALL EXPENSES");size_t page=10;for(size_t start=0;start<a->transactionCount;){printTransactionTableHeader();size_t end=start+page<a->transactionCount?start+page:a->transactionCount;double total=0;for(size_t i=start;i<end;i++){printTransactionTableRow(&a->transactions[i]);total+=a->transactions[i].expense.amount;}printf("Showing %zu-%zu of %zu | Page total: Rs. %.2f\n",start+1,end,a->transactionCount,total);start=end;if(start<a->transactionCount&&!confirm("Continue to the next page? (y/N): "))break;}double total=0;for(size_t i=0;i<a->transactionCount;i++)total+=a->transactions[i].expense.amount;printSeparator();printf("Total records: %zu | Lifetime total: Rs. %.2f\n",a->transactionCount,total);}
static void printMatches(const AppState *a,const size_t *indices,size_t count){if(!count){printInfo("No matching expenses found.");return;}printTransactionTableHeader();double total=0;for(size_t j=0;j<count;j++){printTransactionTableRow(&a->transactions[indices[j]]);total+=a->transactions[indices[j]].expense.amount;}printSeparator();printf("Matches: %zu | Total: Rs. %.2f\n",count,total);}
static int containsInsensitive(const char *text,const char *query){size_t n=strlen(query);if(!n)return 1;for(;*text;text++){size_t i=0;while(i<n&&text[i]&&tolower((unsigned char)text[i])==tolower((unsigned char)query[i]))i++;if(i==n)return 1;}return 0;}
static int sameInsensitive(const char *a,const char *b){return strlen(a)==strlen(b)&&containsInsensitive(a,b);}
void searchExpenses(const AppState *a){if(!a->transactionCount){printInfo("No expense records are available.");return;}for(;;){printSection("SEARCH EXPENSES");puts("  1  Search by ID           2  Search by date");puts("  3  Search by category     4  Search by amount");puts("  5  Search by payment      6  Search description");puts("  0  Return to main menu\n");int c;if(!readInt("Select a search option: ",0,6,&c)){if(feof(stdin))return;continue;}if(!c)return;size_t *matches=malloc(a->transactionCount*sizeof *matches);if(!matches){printError("Memory allocation failed.");return;}size_t n=0;int id=0;double amount=0;char query[DESCRIPTION_SIZE];ExpenseCategory cat=OTHER;char label[CATEGORY_NAME_SIZE]={0};int payment=-1;
        if(c==1&&!readInt("Expense ID: ",1,2147483647,&id)){free(matches);continue;}if(c==2){if(!readRequiredString("Date (DD-MM-YYYY): ",query,sizeof query)||!validDateInput(query)){printError("Invalid date.");free(matches);continue;}}if(c==3&&!chooseCategory(a,&cat,label)){free(matches);continue;}if(c==4&&!readDouble("Amount: ",0,1000000000,&amount)){free(matches);continue;}if(c==5){int p;if(!readInt("Payment (1 Cash, 2 UPI, 3 Card): ",1,3,&p)){free(matches);continue;}payment=p-1;}if(c==6&&!readRequiredString("Description contains: ",query,sizeof query)){free(matches);continue;}
        for(size_t i=0;i<a->transactionCount;i++){const Transaction *t=&a->transactions[i];int ok=0;switch(c){case 1:ok=t->expense.id==id;break;case 2:ok=!strcmp(t->expense.date,query);break;case 3:ok=!strcmp(categoryName(t),label[0]?label:CATEGORY_NAMES[cat]);break;case 4:ok=t->expense.amount==amount;break;case 5:ok=(int)t->paymentType==payment;break;case 6:ok=containsInsensitive(t->expense.description,query);break;}if(ok)matches[n++]=i;}printMatches(a,matches,n);free(matches);}}
static int selectExisting(AppState *a,int *idx){int id;if(!readInt("Expense ID: ",1,2147483647,&id))return 0;*idx=findExpenseById(a,id);if(*idx<0){printWarning("Expense ID not found.");return 0;}return 1;}
static void editString(const char *prompt,char *field,size_t size,bool required){char in[DESCRIPTION_SIZE];if(readOptionalString(prompt,in,size)&&in[0])snprintf(field,size,"%s",in);else if(required&&!*field)readRequiredString(prompt,field,size);}
int updateExpense(AppState *a){int ix;if(!selectExisting(a,&ix))return 0;Transaction old=a->transactions[ix],next=old;printTransaction(&old);printInfo("Leave text fields blank to keep them; enter 0 to keep the current amount.");editString("Date: ",next.expense.date,sizeof next.expense.date,true);if(!validDateInput(next.expense.date)){printError("Invalid date; update cancelled.");return 0;}
    if(confirm("Change category? (y/N): ")){if(!chooseCategory(a,&next.expense.category,next.expense.categoryLabel))return 0;}
    editString("Description: ",next.expense.description,sizeof next.expense.description,true);
    double amt;if(!readDouble("New amount (0 keeps current): ",0,1000000000,&amt))return 0;if(amt>0&&validateAmount(amt))next.expense.amount=amt;
    if(confirm("Change payment method? (y/N): ")&&!choosePayment(&next))return 0;
    printInfo("Review the proposed changes:");printTransaction(&next);if(!confirm("Apply update? (y/N): ")){printInfo("Update cancelled.");return 0;}a->transactions[ix]=next;if(!saveExpenses(a)){a->transactions[ix]=old;printError("Update failed; original record restored.");return 0;}printSuccess("Expense updated.");return 1;}
int deleteExpense(AppState *a){int ix;if(!selectExisting(a,&ix))return 0;Transaction old=a->transactions[ix];printTransaction(&old);if(!confirm("Permanently delete this expense? (y/N): ")){printInfo("Deletion cancelled.");return 0;}memmove(&a->transactions[ix],&a->transactions[ix+1],(a->transactionCount-(size_t)ix-1)*sizeof *a->transactions);a->transactionCount--;if(!saveExpenses(a)){memmove(&a->transactions[ix+1],&a->transactions[ix],(a->transactionCount-(size_t)ix)*sizeof *a->transactions);a->transactions[ix]=old;a->transactionCount++;printError("Delete failed; original record restored.");return 0;}printSuccess("Expense deleted.");return 1;}

static int cmpTx(const Transaction *a,const Transaction *b,int mode){switch(mode){case 1:return (a->expense.amount>b->expense.amount)-(a->expense.amount<b->expense.amount);case 2:return (a->expense.amount<b->expense.amount)-(a->expense.amount>b->expense.amount);case 3:case 4:{Date x,y;parseDate(a->expense.date,&x);parseDate(b->expense.date,&y);int c=compareDates(x,y);return mode==3?c:-c;}case 5:return strcmp(categoryName(a),categoryName(b));default:return (a->expense.id>b->expense.id)-(a->expense.id<b->expense.id);}}
static void printList(const Transaction *list,size_t n){if(!n){printInfo("No records match this view.");return;}printTransactionTableHeader();for(size_t i=0;i<n;i++)printTransactionTableRow(&list[i]);printSeparator();printf("Records: %zu\n",n);}
void sortAndFilterExpenses(const AppState *a){if(!a->transactionCount){printInfo("No expense records are available.");return;}Transaction *copy=malloc(a->transactionCount*sizeof *copy);if(!copy){printError("Memory allocation failed.");return;}memcpy(copy,a->transactions,a->transactionCount*sizeof *copy);for(;;){printSection("SORT AND FILTER");puts("  1  Amount ascending       2  Amount descending");puts("  3  Date ascending         4  Date descending");puts("  5  Category A to Z        6  Expense ID");puts("  7  Filter by category     8  Filter by payment");puts("  9  Filter by month       10  Filter by amount range");puts("  0  Return to main menu\n");int c;if(!readInt("Select an option: ",0,10,&c)){if(feof(stdin))break;continue;}if(!c)break;if(c<=6){for(size_t i=0;i<a->transactionCount;i++)for(size_t j=0;j+1<a->transactionCount-i;j++)if(cmpTx(&copy[j],&copy[j+1],c)>0){Transaction t=copy[j];copy[j]=copy[j+1];copy[j+1]=t;}printList(copy,a->transactionCount);}
        else {size_t n=0;Transaction *filtered=malloc(a->transactionCount*sizeof *filtered);if(!filtered){printError("Memory allocation failed.");continue;}ExpenseCategory cat=OTHER;char label[CATEGORY_NAME_SIZE]={0};int pay=-1,m=0,y=0;double low=0,high=0;int valid=1;
            if(c==7)valid=chooseCategory(a,&cat,label);if(c==8){if(readInt("Payment (1 Cash, 2 UPI, 3 Card): ",1,3,&pay))pay--;else valid=0;}if(c==9)valid=readInt("Month: ",1,12,&m)&&readInt("Year: ",1,9999,&y);if(c==10)valid=readDouble("Minimum amount: ",0,1e9,&low)&&readDouble("Maximum amount: ",low,1e9,&high);
            if(valid)for(size_t i=0;i<a->transactionCount;i++){const Transaction *t=&a->transactions[i];int ok=0;if(c==7)ok=!strcmp(categoryName(t),label[0]?label:CATEGORY_NAMES[cat]);else if(c==8)ok=(int)t->paymentType==pay;else if(c==9){Date d;ok=parseDate(t->expense.date,&d)&&d.month==m&&d.year==y;}else ok=t->expense.amount>=low&&t->expense.amount<=high;if(ok)filtered[n++]=*t;}printList(filtered,n);free(filtered);}}
    free(copy);}

void manageCategories(AppState *a){for(;;){printSection("CATEGORY MANAGEMENT");puts("  1  View categories and spending totals");puts("  2  Add a custom category");puts("  0  Return to main menu\n");int c;if(!readInt("Select an option: ",0,2,&c)){if(feof(stdin))return;continue;}if(!c)return;
        if(c==1){double sums[CATEGORY_COUNT+MAX_CATEGORIES]={0};size_t counts[CATEGORY_COUNT+MAX_CATEGORIES]={0};puts("Categories:");for(int i=0;i<CATEGORY_COUNT;i++)printf("%2d. %s\n",i+1,CATEGORY_NAMES[i]);for(size_t j=0;j<a->categoryCount;j++)printf("%2zu. %s (custom)\n",(size_t)CATEGORY_COUNT+j+1,a->customCategories[j]);for(size_t i=0;i<a->transactionCount;i++){const Transaction *t=&a->transactions[i];size_t ci=categoryIndexForTransaction(a,t);sums[ci]+=t->expense.amount;counts[ci]++;}puts("Totals by category:");for(size_t i=0;i<CATEGORY_COUNT+a->categoryCount;i++)printf("%-20s %3zu transactions  Rs. %.2f\n",categoryDisplayNameAt(a,i),counts[i],sums[i]);}
        else{if(a->categoryCount>=MAX_CATEGORIES){printError("Custom category limit reached.");continue;}char name[CATEGORY_NAME_SIZE];if(!readRequiredString("New category name: ",name,sizeof name))continue;int dup=0;for(int i=0;i<CATEGORY_COUNT;i++)if(sameInsensitive(CATEGORY_NAMES[i],name))dup=1;for(size_t i=0;i<a->categoryCount;i++)if(sameInsensitive(a->customCategories[i],name))dup=1;if(dup){printWarning("That category already exists.");continue;}if(!reserveCategories(a,a->categoryCount+1)){printError("Memory allocation failed.");continue;}memset(a->customCategories[a->categoryCount],0,CATEGORY_NAME_SIZE);snprintf(a->customCategories[a->categoryCount],CATEGORY_NAME_SIZE,"%s",name);a->categoryCount++;if(!saveCategories(a)){a->categoryCount--;printError("Could not save category.");}else printSuccess("Custom category added.");}}}
